	RefineInformation(pkTarget->GetCell(), REFINE_TYPE_NO_REDUCTION_WHEN_FAIL, pkItem->GetCell(), bEkwItemWindow, bEkwScrollWindow);
else if (pkItem->GetValue(0) == REFINE_BONUS_SCROLL)
{
	if (pkTarget && pkTarget->GetType() == ITEM_WEAPON && pkTarget->GetLimitValue(0) == 30) // blokada uzycia na FMSy itp.
		return false;

	RefineInformation(pkTarget->GetCell(), REFINE_TYPE_SCROLL, pkItem->GetCell(), bEkwItemWindow, bEkwScrollWindow);
}
else
{
	if (IsEliteRefine(pkTarget->GetRefineSet())) return false;
	RefineInformation(pkTarget->GetCell(), REFINE_TYPE_SCROLL, pkItem->GetCell(), bEkwItemWindow, bEkwScrollWindow);
}

